contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        require(feeRate <= 5000);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        address beforeBaseToken = c.baseToken();
        address beforeNft = c.nft();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint56 beforeChangeFee = c.changeFee();
        uint16 beforeFeeRate = c.feeRate();
        bytes32 beforeMerkleRoot = c.merkleRoot();
        bool beforeUseStolenNftOracle = c.useStolenNftOracle();
        bool beforePayRoyalties = c.payRoyalties();
        bool beforeInitialized = c.initialized();

        bool reverted;
        try c.initialize(
            address(0xdead),
            address(0xbeef),
            type(uint128).max,
            type(uint128).max,
            type(uint56).max,
            0,
            bytes32(uint256(0x1234)),
            !useStolenNftOracle,
            !payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            beforeInitialized &&
            c.initialized() &&
            c.baseToken() == beforeBaseToken &&
            c.nft() == beforeNft &&
            c.virtualBaseTokenReserves() == beforeVirtualBaseTokenReserves &&
            c.virtualNftReserves() == beforeVirtualNftReserves &&
            c.changeFee() == beforeChangeFee &&
            c.feeRate() == beforeFeeRate &&
            c.merkleRoot() == beforeMerkleRoot &&
            c.useStolenNftOracle() == beforeUseStolenNftOracle &&
            c.payRoyalties() == beforePayRoyalties
        );
    }

    receive() external payable {}
}

