contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 outputAmount) public {
        uint128 vB = c.virtualBaseTokenReserves();
        uint128 vN = c.virtualNftReserves();
        uint16 fRate = c.feeRate();
        address ft = c.baseToken();
        address fac = c.factory();

        require(outputAmount < uint256(vN), "outputAmount must be less than virtualNftReserves");
        require(uint256(vN) - outputAmount > 0, "nonzero denominator");

        uint256 protocolFeeRate = Factory(fac).protocolFeeRate();

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 inputAmount = (outputAmount * uint256(vB)) / (uint256(vN) - outputAmount);
        if (outputAmount * uint256(vB) % (uint256(vN) - outputAmount) != 0) {
            inputAmount += 1;
        }

        uint256 expectedProtocolFeeAmount = inputAmount * uint256(protocolFeeRate) / 10_000;
        uint256 expectedFeeAmount = inputAmount * uint256(fRate) / 10_000;
        uint256 expectedNetInputAmount = inputAmount + expectedFeeAmount + expectedProtocolFeeAmount;

        bool stateUnchanged = c.baseToken() == ft && c.virtualBaseTokenReserves() == vB && c.virtualNftReserves() == vN && c.feeRate() == fRate;

        assert(
            netInputAmount == expectedNetInputAmount &&
            feeAmount == expectedFeeAmount &&
            protocolFeeAmount == expectedProtocolFeeAmount &&
            stateUnchanged
        );
    }
}

