contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}

    function run(uint256 depositAmount, uint256 tokenId) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        address nft = c.nft();
        uint256 beforeBalance = ERC721(nft).balanceOf(address(c));
        uint256 beforePoolBalance = address(c).balance;

        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;

        bool depositReverted;
        try c.deposit{value: depositAmount}(tokenIds, depositAmount) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 afterBalance = ERC721(nft).balanceOf(address(c));
        uint256 afterPoolBalance = address(c).balance;

        assert(!depositReverted);
        assert(afterBalance == beforeBalance + 1);
        assert(afterPoolBalance == beforePoolBalance + depositAmount);
    }
}

