            reverted = true;
        }

        assert(
            reverted ||
            (
                c.virtualBaseTokenReserves() == vbBefore
                && c.virtualNftReserves() == vnBefore + uint128(inputWeight) - uint128(outputWeight)
            )
        );
    }
}
